UPDATE coding_problems
SET starter_code_java = 'import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));\n        String arrayLine = reader.readLine();\n        int target = Integer.parseInt(reader.readLine().trim());\n        int[] nums = Arrays.stream(arrayLine.replace("[", "").replace("]", "").split(","))\n                .mapToInt(value -> Integer.parseInt(value.trim())).toArray();\n        int[] result = new Solution().twoSum(nums, target);\n        System.out.println("[" + result[0] + "," + result[1] + "]");\n    }\n}\n\nclass Solution {\n    public int[] twoSum(int[] nums, int target) {\n        Map<Integer, Integer> seen = new HashMap<>();\n        for (int i = 0; i < nums.length; i++) {\n            int needed = target - nums[i];\n            if (seen.containsKey(needed)) return new int[] { seen.get(needed), i };\n            seen.put(nums[i], i);\n        }\n        return new int[0];\n    }\n}'
WHERE slug = 'two-sum';

UPDATE coding_problems
SET starter_code_java = 'import java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        String input = new BufferedReader(new InputStreamReader(System.in)).readLine().trim();\n        System.out.println(new Solution().reverseList(input));\n    }\n}\n\nclass Solution {\n    public String reverseList(String input) {\n        if (input.isEmpty() || input.equals("null")) return "null";\n        String[] values = input.replace("->null", "").split("->");\n        StringBuilder output = new StringBuilder();\n        for (int i = values.length - 1; i >= 0; i--) {\n            if (output.length() > 0) output.append("->");\n            output.append(values[i]);\n        }\n        return output.append("->null").toString();\n    }\n}'
WHERE slug = 'reverse-linked-list';
